using System.Linq;using UnityEngine;
public static class InspectOrganicContact {public static object Main(){var w=Object.FindAnyObjectByType<ExplorationWorld>();var p=new Vector3(-8.44f,50,-144.11f);Physics.SyncTransforms();return new{vehicle=w.vehicle.position.ToString(),key=w.TileAt(p).ToString(),tiles=w.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("Exploration tile")&&(t.position-new Vector3(-136,0,-264)).sqrMagnitude<1).Select(t=>new{name=t.name,pos=t.position.ToString(),colliders=t.GetComponentsInChildren<MeshCollider>().Select(c=>new{name=c.name,enabled=c.enabled,bounds=c.bounds.ToString(),hit=c.Raycast(new Ray(p,Vector3.down),out var h,100),mesh=c.sharedMesh==null?0:c.sharedMesh.vertexCount}).ToArray()}).ToArray(),allHits=Physics.RaycastAll(p,Vector3.down,100).Select(h=>new{name=h.collider.name,p=h.point.ToString()}).ToArray()};}}
